<?php
namespace ZinCelestial\Platform\Audit;use RuntimeException;defined('ABSPATH')||exit;
final class LegalHoldService{public function __construct(private \wpdb $db,private string $holds,private string $audit,private int $site_id){}public function create(string $reason,int $requester,int $approver,int $from,int $through):string{if($requester<1||$approver<1||$requester===$approver||$from<1||$through<$from)throw new RuntimeException('Dual-control legal hold required.');$id=wp_generate_uuid4();$this->db->query('START TRANSACTION');try{$ok=$this->db->insert($this->holds,['site_id'=>$this->site_id,'hold_id'=>$id,'reason_hash'=>hash('sha256',$reason),'requester_id'=>$requester,'approver_id'=>$approver,'from_sequence'=>$from,'through_sequence'=>$through,'status'=>'active','created_at'=>current_time('mysql',true)]);if($ok!==1)throw new RuntimeException('Hold creation failed.');$n=$this->db->query($this->db->prepare("UPDATE {$this->audit} SET legal_hold=1 WHERE site_id=%d AND sequence_id BETWEEN %d AND %d",$this->site_id,$from,$through));if($n===false)throw new RuntimeException('Hold application failed.');$this->db->query('COMMIT');return$id;}catch(\Throwable $e){$this->db->query('ROLLBACK');throw$e;}}public function release(string $id,int $requester,int $approver):void{if($requester===$approver)throw new RuntimeException('Dual-control hold release required.');throw new RuntimeException('Release requires coverage recomputation and is disabled until implemented.');}}
